301	    /**
302	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city} or
303	     * {@code telephone} is missing or blank (including whitespace-only values that Bean Validation
304	     * does not catch). The names of all offending fields are collected so the caller receives a
305	     * 400 response whose {@code errors} array lists each one.
306	     */
307	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
308	        List<String> missingFields = new ArrayList<>();
309	        if (isBlank(ownerFieldsDto.getFirstName())) {
310	            missingFields.add("firstName");
311	        }
312	        if (isBlank(ownerFieldsDto.getLastName())) {
313	            missingFields.add("lastName");
314	        }
315	        if (isBlank(ownerFieldsDto.getAddress())) {
316	            missingFields.add("address");
317	        }
318	        if (isBlank(ownerFieldsDto.getCity())) {
319	            missingFields.add("city");
320	        }
321	        if (isBlank(ownerFieldsDto.getTelephone())) {
322	            missingFields.add("telephone");
323	        }
324	        if (!missingFields.isEmpty()) {
325	            throw new InvalidOwnerFieldsException(missingFields);
326	        }
327	    }
328	
329	    private static boolean isBlank(String value) {
330	        return value == null || value.trim().isEmpty();
331	    }
332	
333	    /**
334	     * Normalizes an owner's {@code address} on create and writes the canonical form back onto the
335	     * request so it is what gets validated, compared, stored and returned. The value is trimmed,
336	     * runs of internal whitespace are collapsed to a single space, the result is upper-cased and
337	     * common street-type abbreviations are expanded as whole tokens ({@code ST}->{@code STREET},
338	     * {@code RD}->{@code ROAD}, {@code AVE}->{@code AVENUE}). Running before the required-field check
339	     * means an address that is blank after normalization is rejected like a missing one.
340	     */
341	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
342	        ownerFieldsDto.setAddress(canonicalAddress(ownerFieldsDto.getAddress()));
343	    }
344	
345	    /**
346	     * Returns the canonical form of an address: trimmed, internal whitespace runs collapsed to a
347	     * single space, upper-cased, with common street-type abbreviations expanded as whole tokens. A
348	     * {@code null} value returns {@code null}. The transform is idempotent, so an already-canonical
349	     * address is returned unchanged, making it safe to apply to stored values during comparison.
350	     */
351	    private static String canonicalAddress(String address) {
352	        if (address == null) {
353	            return null;
354	        }
355	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
356	        if (collapsed.isEmpty()) {
357	            return "";
358	        }
359	        String[] tokens = collapsed.split(" ");
360	        StringBuilder sb = new StringBuilder(collapsed.length());
361	        for (int i = 0; i < tokens.length; i++) {
362	            if (i > 0) {
363	                sb.append(' ');
364	            }
365	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
366	        }
367	        return sb.toString();
368	    }
369	
370	    /**
371	     * Normalizes an owner's {@code telephone} on create into E.164 form. A leading {@code '+'} and
372	     * the country code that follows it are kept; otherwise the country code {@code '+61'} is assumed
373	     * and a single leading {@code '0'} is dropped from the national digits. Spaces, dashes and
374	     * brackets are stripped. The result must have 8 to 15 digits after the {@code '+'}, and when the
375	     * country code is one whose national-number length is known ({@code '+61'} => 9 national digits,
376	     * {@code '+1'} => 10) the national number must have exactly that many digits. The E.164 string is
377	     * written back onto the request so it is what gets stored and returned. Any value that cannot
378	     * form a valid E.164 number is rejected with a 400 response whose {@code errors} array names
379	     * {@code telephone}.
380	     */
381	    private void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
382	        ownerFieldsDto.setTelephone(toE164(ownerFieldsDto.getTelephone()));
383	    }
384	
385	    /**
386	     * Converts a raw telephone value to E.164 form, or throws {@link InvalidOwnerFieldsException}
387	     * (400) naming {@code telephone} when it cannot form a valid number.
388	     */
389	    private static String toE164(String telephone) {
390	        if (telephone == null) {
391	            throw new InvalidOwnerFieldsException(List.of("telephone"));
392	        }
393	        boolean hasCountryCode = telephone.trim().startsWith("+");
394	        String digits = telephone.replaceAll("\\D", "");
395	        String countryCode;
396	        String national;
397	        if (hasCountryCode) {
398	            countryCode = matchCountryCode(digits);
399	            national = digits;
400	        } else {
401	            countryCode = "61";
402	            if (digits.startsWith("0")) {
403	                digits = digits.substring(1);
404	            }
405	            national = "61" + digits;
406	        }
407	        if (!national.matches("[0-9]{8,15}")) {
408	            throw new InvalidOwnerFieldsException(List.of("telephone"));
409	        }
410	        if (countryCode != null) {
411	            Integer requiredLength = COUNTRY_NATIONAL_LENGTH.get(countryCode);
412	            if (requiredLength != null
413	                && national.length() - countryCode.length() != requiredLength) {
414	                throw new InvalidOwnerFieldsException(List.of("telephone"));
415	            }
416	        }
417	        return "+" + national;
418	    }
419	
420	    /**
421	     * Returns the longest known E.164 country code (a key of {@link #COUNTRY_NATIONAL_LENGTH}) that
422	     * the given country-code-prefixed digit string starts with, or {@code null} when none is known so
423	     * the number is not length-checked against a country.
424	     */
425	    private static String matchCountryCode(String digits) {
426	        return COUNTRY_NATIONAL_LENGTH.keySet().stream()
427	            .filter(digits::startsWith)
428	            .max(Comparator.comparingInt(String::length))
429	            .orElse(null);
430	    }
431	
432	    /**
433	     * Rejects creating an owner whose derived {@code identityKey} already, in its entirety, belongs
434	     * to another owner. The key is {@code normalizedTelephone + '|' + (email or empty) + '|' +
435	     * (householdId or empty)}, so it folds the former separate telephone, email and household
436	     * duplicate checks into one: only an exact full-key match is a duplicate. In particular two
437	     * members of the same household (same {@code householdId}) with different telephones have
438	     * different keys and are both allowed. The incoming telephone and email have already been
439	     * normalized by {@link #normalizeTelephone} and {@link #normalizeEmail}, and the household id has
440	     * been resolved by {@link #resolveHouseholdId}; each existing owner's key is derived the same way
441	     * before comparison. A match results in a 409 response naming {@code identityKey}.
442	     */
443	    private void rejectDuplicateIdentity(OwnerFieldsDto ownerFieldsDto, String householdId) {
444	        String identityKey = identityKey(ownerFieldsDto.getTelephone(), ownerFieldsDto.getEmail(), householdId);
445	        for (Owner existing : this.clinicService.findAllOwners()) {
446	            if (identityKey.equals(existingIdentityKey(existing))) {
447	                throw new DuplicateOwnerIdentityException(identityKey);
448	            }
449	        }
450	    }
451	
452	    /**
453	     * Builds an {@code identityKey} from its three parts: {@code telephone + '|' + email + '|' +
454	     * householdId}, with a {@code null} part contributing the empty string. The telephone and email
455	     * are expected to already be in their normalized (E.164, lower-cased) forms.
456	     */
457	    private static String identityKey(String telephone, String email, String householdId) {
458	        return orEmpty(telephone) + "|" + orEmpty(email) + "|" + orEmpty(householdId);
459	    }
460	
461	    /**
462	     * Derives an already-stored owner's {@code identityKey} for duplicate comparison: the stored
463	     * telephone is converted to E.164 form (or the empty string when it cannot form a valid number),
464	     * the stored email is lower-cased, and the stored household id is used as-is.
465	     */
466	    private static String existingIdentityKey(Owner existing) {
467	        String telephone = orEmpty(normalizeExisting(existing.getTelephone()));
468	        String email = existing.getEmail() == null ? "" : existing.getEmail().toLowerCase(Locale.ROOT);
469	        return identityKey(telephone, email, existing.getHouseholdId());
470	    }
471	
472	    private static String orEmpty(String value) {
473	        return value == null ? "" : value;
474	    }
475	
476	    /**
477	     * Returns the E.164 form of an already-stored telephone for duplicate comparison, or {@code null}
478	     * when the stored value cannot form a valid E.164 number (so it never matches an incoming one).
479	     */
480	    private static String normalizeExisting(String telephone) {
481	        try {
482	            return toE164(telephone);
483	        } catch (InvalidOwnerFieldsException ex) {
484	            return null;
485	        }
486	    }
487	
488	    /**
489	     * Rejects creating an owner in a city that has reached capacity: a city that already contains
490	     * {@value #MAX_OWNERS_PER_CITY} or more owners cannot take another one. Existing owners are
491	     * counted with a case-insensitive match on {@code city}, the same way {@link #assignCustomerCode}
492	     * groups a city. A city at or over the limit results in a 409 response naming {@code city}.
493	     */
494	    private void rejectCityAtCapacity(OwnerFieldsDto ownerFieldsDto) {
495	        String city = ownerFieldsDto.getCity();
496	        int count = 0;
497	        for (Owner existing : this.clinicService.findAllOwners()) {
498	            if (city.equalsIgnoreCase(existing.getCity())) {
499	                count++;
500	            }
501	        }
502	        if (count >= MAX_OWNERS_PER_CITY) {
503	            throw new OwnerCityAtCapacityException(city);
504	        }
505	    }
506	
507	    /**
508	     * Rejects creating an owner once {@value #MAX_OWNERS_PER_DAY} or more owners already carry the
509	     * given adjusted business-day {@code registrationDate}, counted by an exact match. The date has
510	     * already been resolved and rolled forward off a weekend by {@link #resolveRegistrationDate}, so
511	     * the limit is enforced per business day. A day at or over the limit results in a 429 response.
512	     */
513	    private void rejectDailyLimitReached(LocalDate registrationDate) {
514	        int count = 0;
515	        for (Owner existing : this.clinicService.findAllOwners()) {
516	            if (registrationDate.equals(existing.getRegistrationDate())) {
517	                count++;
518	            }
519	        }
520	        if (count >= MAX_OWNERS_PER_DAY) {
521	            throw new DailyOwnerLimitReachedException(registrationDate);
522	        }
523	    }
524	
525	    /**
526	     * Normalizes a value for case-insensitive, whitespace-insensitive comparison: leading and
527	     * trailing whitespace is trimmed, internal runs of whitespace are collapsed to a single space and
528	     * the result is lower-cased. A {@code null} value normalizes to the empty string.
529	     */
530	    private static String normalizeForComparison(String value) {
531	        if (value == null) {
532	            return "";
533	        }
534	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
535	    }
536	
537	    /**
538	     * Normalizes an owner's optional {@code email}. The field may be omitted entirely, but when a
539	     * value is present it must be a syntactically valid address; the trimmed value is lower-cased and
540	     * written back onto the request so that is what gets stored and returned. A present but invalid
541	     * address is rejected with a 400 response whose {@code errors} array names {@code email}.
542	     */
543	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
544	        String email = ownerFieldsDto.getEmail();
545	        if (email == null) {
546	            return;
547	        }
548	        String trimmed = email.trim();
549	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
550	            throw new InvalidOwnerFieldsException(List.of("email"));
551	        }
552	        ownerFieldsDto.setEmail(trimmed.toLowerCase(Locale.ROOT));
553	    }
554	
555	    /**
556	     * Validates an owner's optional {@code postcode} on create. The field may be omitted entirely
557	     * (so an owner created without a postcode stays accepted), but when a value is present it must be
558	     * exactly 4 digits and valid for the region the owner's {@code city} derives to: NSW 2000-2099,
559	     * VIC 3000-3099, QLD 4000-4099. A city with no known region accepts any 4-digit postcode. A
560	     * present postcode that is malformed or out of range for the city's region is rejected with a 400
561	     * response whose {@code errors} array names {@code postcode}. A valid value is left on the request
562	     * as-is so it is stored and returned.
563	     */
564	    private void validatePostcode(OwnerFieldsDto ownerFieldsDto) {
565	        String postcode = ownerFieldsDto.getPostcode();
566	        if (postcode == null) {
567	            return;
568	        }
569	        if (!postcode.matches("[0-9]{4}")) {
570	            throw new InvalidOwnerFieldsException(List.of("postcode"));
571	        }
572	        int[] range = REGION_POSTCODE_RANGE.get(OwnerLocality.derive(ownerFieldsDto.getCity()));
573	        if (range != null) {
574	            int value = Integer.parseInt(postcode);
575	            if (value < range[0] || value > range[1]) {
576	                throw new InvalidOwnerFieldsException(List.of("postcode"));
577	            }
578	        }
579	    }
580	
581	    /**
582	     * Resolves an owner's effective {@code registrationDate} on create and rolls it onto a business
583	     * day. When the caller supplies no value it defaults to the server's current date; a value
584	     * provided in the request is kept. The effective date, whether supplied or defaulted, must fall
585	     * on a business day: a Saturday or Sunday is rolled forward to the following Monday. The adjusted
586	     * date is written back onto the request so it is what gets stored and returned (in ISO
587	     * {@code YYYY-MM-DD} format) and what every value derived from the registration date is based on.
588	     */
589	    private void resolveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
590	        LocalDate effective = ownerFieldsDto.getRegistrationDate();
591	        if (effective == null) {
592	            effective = LocalDate.now();
593	        }
594	        ownerFieldsDto.setRegistrationDate(toBusinessDay(effective));
595	    }
596	
597	    /**
598	     * Rolls a date forward onto a business day: a Saturday or Sunday is advanced to the following
599	     * Monday; a weekday is returned unchanged.
600	     */
601	    private static LocalDate toBusinessDay(LocalDate date) {
602	        return switch (date.getDayOfWeek()) {
603	            case SATURDAY -> date.plusDays(2);
604	            case SUNDAY -> date.plusDays(1);
605	            default -> date;
606	        };
607	    }
608	
609	    /**
610	     * Assigns the owner's {@code customerCode} on create, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}
611	     * where {@code CITY3} is the upper-cased first three letters of {@code city}, {@code LAST3} is the
612	     * upper-cased first three letters of {@code lastName} and {@code NNNN} is a per-city 4-digit
613	     * zero-padded sequence equal to one more than the number of owners already in that city
614	     * (e.g. {@code 'SYD-SMI-0007'}).
615	     */
616	    private void assignCustomerCode(Owner owner) {
617	        String city = owner.getCity();
618	        String lastName = owner.getLastName();
619	        String cityPrefix = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
620	        String lastPrefix = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
621	        int sequence = 1;
622	        for (Owner existing : this.clinicService.findAllOwners()) {
623	            if (city.equalsIgnoreCase(existing.getCity())) {
624	                sequence++;
625	            }
626	        }
627	        owner.setCustomerCode(String.format("%s-%s-%04d", cityPrefix, lastPrefix, sequence));
628	    }
629	
630	    /**
631	     * Assigns the owner's {@code membershipNumber} on create, formatted
632	     * {@code '<customerCode>-M<YY>'} where {@code YY} is the last two digits of the
633	     * {@code registrationDate} year (e.g. {@code 'SMI-0007-M26'}). Assigned after
634	     * {@link #assignCustomerCode} and once {@code registrationDate} has been defaulted, so both
635	     * inputs are present.
636	     */
637	    private void assignMembershipNumber(Owner owner) {
638	        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
639	        owner.setMembershipNumber(owner.getCustomerCode() + "-M" + yy);
640	    }
641	
642	    /**
643	     * Assigns the new owner's {@code namesakeCount} on create: the number of owners that already
644	     * exist sharing the same {@code firstName} and {@code lastName}, compared case-insensitively.
645	     * Computed before the new owner is persisted, so it counts only the pre-existing owners.
646	     */
647	    private void assignNamesakeCount(Owner owner) {
648	        String firstName = owner.getFirstName();
649	        String lastName = owner.getLastName();
650	        int count = 0;
651	        for (Owner existing : this.clinicService.findAllOwners()) {
652	            if (firstName.equalsIgnoreCase(existing.getFirstName())
653	                && lastName.equalsIgnoreCase(existing.getLastName())) {
654	                count++;
655	            }
656	        }
657	        owner.setNamesakeCount(count);
658	    }
659	
660	    /**
661	     * Assigns the new owner's {@code membershipLevel} on create: a number from 1 to 3 starting at
662	     * 1, plus 1 when an email is present, plus 1 when {@code namesakeCount} is 0, capped at 3.
663	     * Level 4 is reserved for tenure. Runs after {@link #assignNamesakeCount} so that count is
664	     * settled.
665	     */
666	    private void assignMembershipLevel(Owner owner) {
667	        int level = 1;
668	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
669	            level++;
670	        }
671	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
672	            level++;
673	        }
674	        owner.setMembershipLevel(Math.min(level, 3));
675	    }
676	
677	    /**
678	     * Assigns the new owner's {@code bulkSignupWarning} on create: {@code true} when more than
679	     * {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry the new owner's adjusted
680	     * business-day {@code registrationDate}, otherwise {@code false}. Counted the same way as the
681	     * daily-limit rule and computed before the new owner is persisted, so it counts only the
682	     * pre-existing owners for that day.
683	     */
684	    private void assignBulkSignupWarning(Owner owner) {
685	        LocalDate registrationDate = owner.getRegistrationDate();
686	        int count = 0;
687	        for (Owner existing : this.clinicService.findAllOwners()) {
688	            if (registrationDate.equals(existing.getRegistrationDate())) {
689	                count++;
690	            }
691	        }
692	        owner.setBulkSignupWarning(count > BULK_SIGNUP_WARNING_THRESHOLD);
693	    }
694	
695	    /**
696	     * Assigns the new owner's {@code householdId} when the request opts in with
697	     * {@code sharesHousehold} set to {@code true} and at least one existing owner already shares the
698	     * same last name and address (compared case-insensitively with runs of whitespace collapsed, the
699	     * same way {@link #householdMembers} matches). The household's members and the new owner
700	     * all end up carrying one stable shared identifier: if any existing member already has a
701	     * {@code householdId} it is reused, otherwise a new one is derived from the normalized last name
702	     * and address. Any existing member that is missing the identifier is updated so the whole
703	     * household stays consistent. When the flag is absent, or set but no matching owner exists, no
704	     * identifier is assigned.
705	     */
706	    private void assignHousehold(Owner owner, OwnerFieldsDto ownerFieldsDto) {
707	        String householdId = resolveHouseholdId(ownerFieldsDto);
708	        if (householdId == null) {
709	            return;
710	        }
711	        owner.setHouseholdId(householdId);
712	        String lastName = normalizeForComparison(owner.getLastName());
713	        String address = canonicalAddress(owner.getAddress());
714	        for (Owner member : householdMembers(lastName, address)) {
715	            if (!householdId.equals(member.getHouseholdId())) {
716	                member.setHouseholdId(householdId);
717	                this.clinicService.saveOwner(member);
718	            }
719	        }
720	    }
721	
722	    /**
723	     * Resolves, without any mutation, the {@code householdId} a new owner would be assigned, so it
724	     * can feed both the {@code identityKey} duplicate check and the actual {@link #assignHousehold}
725	     * assignment. Returns {@code null} unless the request opts in with {@code sharesHousehold} set to
726	     * {@code true} and at least one existing owner already shares the same normalized last name and
727	     * address; in that case the household's existing stable identifier is reused, or a new one is
728	     * derived from the normalized last name and address when none of the members carries one yet.
729	     */
730	    private String resolveHouseholdId(OwnerFieldsDto ownerFieldsDto) {
731	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
732	            return null;
733	        }
734	        String lastName = normalizeForComparison(ownerFieldsDto.getLastName());
735	        String address = canonicalAddress(ownerFieldsDto.getAddress());
736	        List<Owner> members = householdMembers(lastName, address);
737	        if (members.isEmpty()) {
738	            return null;
739	        }
740	        return members.stream()
741	            .map(Owner::getHouseholdId)
742	            .filter(id -> id != null && !id.isBlank())
743	            .findFirst()
744	            .orElseGet(() -> newHouseholdId(lastName, address));
745	    }
746	
747	    /**
748	     * Returns every existing owner sharing the given normalized last name and address (compared
749	     * case-insensitively with runs of whitespace collapsed), the members of a household.
750	     */
751	    private List<Owner> householdMembers(String normalizedLastName, String normalizedAddress) {
752	        List<Owner> members = new ArrayList<>();
753	        for (Owner existing : this.clinicService.findAllOwners()) {
754	            if (normalizedLastName.equals(normalizeForComparison(existing.getLastName()))
755	                && normalizedAddress.equals(canonicalAddress(existing.getAddress()))) {
756	                members.add(existing);
757	            }
758	        }
759	        return members;
760	    }
761	
762	    /**
763	     * Assigns the new owner's {@code householdMemberCount} on create: the number of owners sharing
764	     * the new owner's {@code householdId} once this create is applied — that is, the new owner plus
765	     * every existing owner already carrying the same identifier. Runs after {@link #assignHousehold}
766	     * so the identifier is settled. Left {@code null} when the owner belongs to no household.
767	     */
768	    private void assignHouseholdMembership(Owner owner) {
769	        String householdId = owner.getHouseholdId();
770	        if (householdId == null || householdId.isBlank()) {
771	            owner.setHouseholdMemberCount(null);
772	            return;
773	        }
774	        int count = 1;
775	        for (Owner existing : this.clinicService.findAllOwners()) {
776	            if (householdId.equals(existing.getHouseholdId())) {
777	                count++;
778	            }
779	        }
780	        owner.setHouseholdMemberCount(count);
781	    }
782	
783	    /**
784	     * Derives a stable household identifier from the normalized last name and address: the first
785	     * twelve upper-case hex characters of the SHA-256 digest of {@code "<lastName>|<address>"}. Two
786	     * owners in the same household therefore derive the same value regardless of creation order.
787	     */
788	    private static String newHouseholdId(String normalizedLastName, String normalizedAddress) {
789	        try {
790	            byte[] digest = MessageDigest.getInstance("SHA-256")
791	                .digest((normalizedLastName + "|" + normalizedAddress).getBytes(StandardCharsets.UTF_8));
792	            StringBuilder hex = new StringBuilder(digest.length * 2);
793	            for (byte b : digest) {
794	                hex.append(String.format("%02x", b));
795	            }
796	            return hex.substring(0, 12).toUpperCase(Locale.ROOT);
797	        } catch (NoSuchAlgorithmException ex) {
798	            throw new IllegalStateException("SHA-256 is required but unavailable", ex);
799	        }
800	    }
801	}
