217	     *
218	     * @param e The {@link MethodArgumentNotValidException} to be handled
219	     * @param request {@link HttpServletRequest} object referring to the current request.
220	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
221	     */
222	    @ExceptionHandler(MethodArgumentNotValidException.class)
223	    @ResponseBody
224	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
225	        HttpStatus status = HttpStatus.BAD_REQUEST;
226	        BindingErrorsResponse errors = new BindingErrorsResponse();
227	        BindingResult bindingResult = e.getBindingResult();
228	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
229	        if (bindingResult.hasErrors()) {
230	            errors.addAllErrors(bindingResult);
231	            List<String> invalidFields = bindingResult.getFieldErrors().stream()
232	                .map(FieldError::getField)
233	                .distinct()
234	                .toList();
235	            detail.setProperty("errors", invalidFields);
236	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
237	                .map(fieldError -> {
238	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
239	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
240	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
241	                        fieldError.getField(),
242	                        defaultMessage,
243	                        rejectedValue);
244	                    return new ValidationMessageDto(message)
245	                        .putAdditionalProperty("field", fieldError.getField())
246	                        .putAdditionalProperty("rejectedValue", rejectedValue)
247	                        .putAdditionalProperty("defaultMessage", defaultMessage);
248	                })
249	                .toList();
250	            logger.debug("Validation error at {} {}: {}",
251	                request.getMethod(),
252	                request.getRequestURI(),
253	                bindingResult.getFieldErrors());
254	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
255	            return ResponseEntity.status(status).body(detail);
256	        }
257	        return ResponseEntity.status(status).body(detail);
258	    }
