    assignMembershipNumber(owner);
    assignNamesakeCount(owner);
    assignMembershipLevel(owner);
    assignBulkSignupWarning(owner);
    assignHousehold(owner, ownerFieldsDto);
    assignHouseholdMembership(owner);
